var n=`0696-igname-pilee`;var t=`world-0696`;var s=`BJ`;var a=`western-africa`;var r=4;var o=58;var d={en:`Igname Pilée`,ua:`Товчений ямс`};var g={en:`Igname Pilée is a Benin classic prepared with yam, peanut sauce. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Товчений ямс, страва кухні країни Бенін зі складниками: ямс, арахісовий соус. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var h=[{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:10,i:[[`yam`,1100,`g`]]},{en:`Cook the listed ingredients in simmering water for about 30 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 30 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:30,i:[[`water`,1300,`ml`],[`table-salt`,5,`g`]]},{en:`Drain the cooked ingredients and pound or mash while warm for about 15 minutes until thick, elastic and smooth; shape into portions with wet hands or a spoon.`,ua:`Злийте воду з готових продуктів і протягом приблизно 15 хвилин товчіть або розминайте теплими до густої гладкої еластичної маси; сформуйте порції вологими руками чи ложкою.`,t:[`mashing`,`pounding`],m:15,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`peanut-sauce`,180,`g`]]}];var u={slug:n,id:t,country:`BJ`,region:a,servings:4,minutes:58,title:d,text:g,steps:h};export{s as country,u as default,t as id,o as minutes,a as region,r as servings,n as slug,h as steps,g as text,d as title};